const tx=k=>T[s.lang][k]||k;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const all=()=>[...data,...s.items];
const cond=d=>Number.isFinite(d.sugar)&&Number.isFinite(d.score)&&d.sugar<=5&&d.score>=8;const hall=d=>cond(d)&&d.sweet==='no'&&(d.sample||!!d.nutriPhoto);const zone=d=>!Number.isFinite(d.sugar)||!Number.isFinite(d.score)?'pending':d.score>=8?(d.sugar<=5?'hof':'cheat'):(d.sugar<=5?'brave':'crime');const unique=()=>{let keys=new Set(),res=[];for(const d of s.items){if(!d.tasted||d.sample)continue;let key=(d.brand+'|'+d.name).toLowerCase().trim();if(keys.has(key))continue;keys.add(key);res.push(d)}return res};const xp=()=>{let x=0,cat=new Set();for(const d of unique()){x+=50;if(Number.isFinite(d.sugar))x+=10;if(d.productPhoto&&d.nutriPhoto)x+=20;if(!cat.has(d.cat)){cat.add(d.cat);x+=20}}return x};const curRank=()=>ranks.reduce((r,v,i)=>xp()>=v[1]?i:r,0);
function pack(d){
 const artwork=(typeof d.art==='string'&&(d.art.startsWith('data:image/')||/^assets\/labels\/[a-z0-9-]+\.svg$/.test(d.art)))?d.art:null;
 const image=artwork?`<img class="label-art" alt="" src="${esc(artwork)}" draggable="false">`:`<div class="label-design"><span class="label-brand">${esc(d.brand||'SODA CULTURE')}</span><strong>${esc(d.name||'NEW DROP')}</strong><span class="label-caption">FIZZMAP® / SODA CULTURE</span></div>`;
 const z=Math.max(1,Math.min(2,Number(d.zoom)||1)),sh=Math.max(-50,Math.min(50,Number(d.shift)||0));
 return `<div class="packstage"><div class="vessel ${d.pack==='bottle'?'bottle':'can'}" style="--can-color:${esc(d.color||'#d8ff52')};--label-zoom:${z};--label-shift:${sh}%" role="img" aria-label="${esc(d.pack==='bottle'?'Flasche':'Dose')} ${esc(d.name||'Drink')}"><div class="vessel-neck"></div><div class="vessel-cap"></div><div class="vessel-body"><div class="vessel-wrap"><div class="vessel-label">${image}</div></div></div></div></div>`;
}
function tag(d){return d.sample?`<span class="fine">${tx('preview')}</span>`:`<span class="fine">MY TASTING</span>`}
function card(d){const finish=d.score>=8.5?'ICON':d.score>=7?'SELECT':'CORE';const serial=String([...String(d.id)].reduce((v,c)=>(v*31+c.charCodeAt(0))>>>0,7)%10000).padStart(4,'0');return `<button class="card collector-card finish-${finish.toLowerCase()}" data-detail="${esc(d.id)}" aria-label="${esc(d.name)} ${finish}"><span class="card-sheen"></span><div class="card-top"><span>FIZZMAP® / CARD INDEX</span><b>✳ ${finish}</b></div><div class="card-art">${pack(d)}<span class="art-halo"></span></div><div class="card-foot"><div class="card-serial">NO. ${serial} / ${d.sample?'STUDIO':'COLLECTOR'}</div><div class="card-brand">${esc(d.brand)}</div><h3>${esc(d.name)}</h3><div class="card-data"><span>${tx('sugar')} / 100ml <b>${d.sugar==null?'—':Number(d.sugar).toFixed(1)+'g'}</b></span><span>${tx('taste')} <b>${Number.isFinite(d.score)?d.score.toFixed(1):'—'}/10</b></span></div><div class="card-sign"><span>${d.sample?'FIZZMAP STUDIO':d.tasted?'TASTED':'WISHLIST'}</span><span>✳ 2026</span></div></div></button>`}
function daily(){let picks=[...s.items.filter(d=>d.tasted&&hall(d)),...data.filter(hall)];let i=Math.floor(Date.now()/86400000)%picks.length,d=picks[i],d2=picks[(i+1)%picks.length],d3=picks[(i+2)%picks.length];return `<section class="section"><div class="section-title"><div><div class="key">FIZZMAP / DAILY EDIT</div><h2>${tx('daily')}<span class="lime">.</span></h2></div><span class="pill">24H DROP</span></div><p class="muted" style="margin-bottom:13px">${tx('dailySub')}</p><div class="daily"><div class="daily-art">${pack(d)}</div><div class="daily-right"><span class="pill">✳ EDITOR'S PICK</span><h3>${esc(d.name)}</h3><p class="muted">${esc(d.brand)}<br><b>${Number.isFinite(d.sugar)?d.sugar.toFixed(1):'—'} g</b> /100 ml · <b>${d.score.toFixed(1)}</b> TASTE</p><button class="cta" data-detail="${d.id}">${tx('view')} ↗</button></div></div><div class="runner">${[d2,d3].map(x=>`<button data-detail="${x.id}"><small>${tx('more')} / ${x.cat.toUpperCase()}</small><b>${esc(x.name)}</b><small>${x.score.toFixed(1)}/10 · ${x.sugar.toFixed(1)}g</small></button>`).join('')}</div></section>`}
function features(){let classic=data[1],sw=data[0],saving=(classic.sugar-sw.sugar)*3.3;return `<section class="features"><div class="feature"><div class="key">01 / THE SUGAR SWITCH</div><h2>${tx('feature1')}</h2><p class="muted">${tx('feature1sub')}</p><div class="mini-comparison"><b>−${saving.toFixed(1).replace('.',',')} g</b><small>${s.lang==='de'?'Zucker bei 330 ml im Mustervergleich':'sugar per 330 ml in sample comparison'}</small></div><button class="cta" data-feature="swap">${tx('battle')} ↗</button></div><div class="feature pink"><div class="key">02 / THE MANUFACTURER CALL-OUT</div><h2>${tx('feature2')}</h2><p class="muted">${tx('feature2sub')}</p><button class="cta ghost" data-feature="manifesto">${tx('challenge')} ↗</button></div></section>`}
function home(){return `<div class="hero"><div class="key">THE INDEPENDENT SODA CULTURE INDEX</div><h1>${tx('hero')}</h1><p class="lead">${tx('intro')}</p></div><div class="pad">${daily()}${features()}<section class="section"><div class="section-title"><h2>FIZZ SIGNAL<span class="lime">.</span></h2><span class="pill">THE CULTURE</span></div><div class="signal"><div><div class="key">THE GOLD STANDARD</div><b>${s.lang==='de'?'Mehr Genuss. Weniger Zucker. Keine Abkürzungen.':'More taste. Less sugar. No shortcuts.'}</b></div><button class="cta" data-nav="map">◎</button></div></section></div>`}
function plot(){let x0=35,x1=407,y0=23,y1=291,cx=x0+(x1-x0)*5/16,cy=y1-(y1-y0)*.8;let gx=Array.from({length:9},(_,i)=>`<line x1="${x0+i*(x1-x0)/8}" x2="${x0+i*(x1-x0)/8}" y1="${y0}" y2="${y1}" stroke="#ffffff1a"/><line x1="${x0}" x2="${x1}" y1="${y0+i*(y1-y0)/8}" y2="${y0+i*(y1-y0)/8}" stroke="#ffffff1a"/>`).join('');let dots=all().filter(d=>Number.isFinite(d.sugar)&&Number.isFinite(d.score)).map(d=>{let cx1=x0+Math.min(16,Math.max(0,d.sugar))/16*(x1-x0),cy1=y1-Math.min(10,Math.max(0,d.score))/10*(y1-y0);return `<g data-point="${esc(d.id)}" tabindex="0" role="button" aria-label="${esc(d.name)}"><circle cx="${cx1}" cy="${cy1}" r="10" stroke="${d.sweet==='yes'?'#ffc0d3':'#102017'}" stroke-width="${d.sweet==='yes'?3:3}" stroke-dasharray="${d.sweet==='yes'?'3 3':'none'}" fill="${s.peek===d.id?'#d8ff52':'#f5f9f1'}"/><title>${esc(d.name)}, ${d.score}/10, ${d.sugar}g</title></g>`}).join('');let d=all().find(v=>v.id===s.peek);return `<div class="map-shell"><div class="map-tools"><b>◎ TASTE × SUGAR</b><div class="switch"><button class="${s.mode==='personal'?'on':''}" data-mode="personal">${tx('mapPersonal')}</button><button class="${s.mode==='global'?'on':''}" data-mode="global">${tx('mapGlobal')}</button></div></div><div class="plot-holder"><svg class="plot" viewBox="0 0 425 353" role="img" aria-label="FIZZMAP Taste and sugar chart"><rect x="${x0}" y="${y0}" width="${cx-x0}" height="${cy-y0}" fill="#365e43"/><rect x="${cx}" y="${y0}" width="${x1-cx}" height="${cy-y0}" fill="#6e5638"/><rect x="${x0}" y="${cy}" width="${cx-x0}" height="${y1-cy}" fill="#2c5057"/><rect x="${cx}" y="${cy}" width="${x1-cx}" height="${y1-cy}" fill="#583743"/>${gx}<path d="M ${cx} ${y0} V ${y1} M ${x0} ${cy} H ${x1}" stroke="#dbff55" stroke-width="1.5" stroke-dasharray="5 4"/><text x="43" y="36" font-size="10" font-weight="950" fill="#baffa7">HALL OF</text><text x="43" y="48" font-size="10" font-weight="950" fill="#baffa7">FAME ✳</text><text x="${cx+10}" y="40" font-size="12" font-weight="950" fill="#ffe0a3">CHEATCODE SUGAR</text><text x="44" y="${cy+21}" font-size="10" font-weight="950" fill="#aaf0f0">BRAVE BUT</text><text x="44" y="${cy+35}" font-size="10" font-weight="950" fill="#aaf0f0">FLAT</text><text x="${cx+10}" y="${cy+23}" font-size="12" font-weight="950" fill="#ffc0d3">CRIME SCENE</text>${s.mode==='personal'?dots:''}<text x="11" y="29" fill="#eaf4e7" font-size="10">10</text><text x="19" y="288" fill="#eaf4e7" font-size="10">0</text><text x="34" y="310" fill="#eaf4e7" font-size="10">0</text><text x="${cx-2}" y="310" fill="#d8ff52" font-size="10">5</text><text x="379" y="310" fill="#eaf4e7" font-size="10">16+</text><text x="132" y="339" font-size="12" font-weight="900" fill="#ebf5e7">${tx('x')} →</text><text transform="rotate(-90 12 210)" x="12" y="210" font-size="10" font-weight="900" fill="#d8ff52">↑ ${tx('taste')} / 10</text></svg>${s.mode==='global'?`<div class="overlay"><h3>GLOBAL / COMING SOON</h3><p>${tx('globalText')}</p><button class="cta" data-mode="personal">${tx('mapPersonal')}</button></div>`:''}${d&&s.mode==='personal'?`<div class="peek"><div><span class="mini-tag">QUICK PEEK / ${cond(d)&&!hall(d)?'HALL GATE NOT CLEARED':zones[zone(d)][0]}</span></div><button data-close class="close">×</button><h3>${esc(d.name)}</h3><p class="muted">${Number.isFinite(d.score)?d.score.toFixed(1):'—'}/10 · ${Number.isFinite(d.sugar)?d.sugar.toFixed(1):'—'} g/100 ml<br><b style="color:${hall(d)?'#d8ff52':'#ffc0d3'}">${hall(d)?tx('eligible'):tx('excluded')}</b> / ${tx('sweet')}: ${tx(d.sweet)}</p><button class="cta" data-detail="${esc(d.id)}">${tx('view')} ↗</button></div>`:''}</div><div class="map-tip"><span><b>≤5g + ≥8/10 + NO SWEETENERS</b></span><span>${tx('tap')}</span></div><p class="map-status">${tx('mapGoal')} · ✳ ${tx('mapText')}</p></div>`}
function mapPage(){return `<div class="map-hero"><div class="key">THE FLAGSHIP / FIZZMAP®</div><h1>THE TASTE<br><span class="lime">FRONTIER.</span></h1><p class="lead">${tx('mapIntro')}</p></div>${plot()}<div class="pad"><section class="section"><div class="section-title"><h2>${tx('zTitle')}<span class="lime">.</span></h2><span class="pill">THE RULEBOOK</span></div>${['hof','cheat','brave','crime'].map((z,i)=>`<div class="zone" style="--tone:${zones[z][1]}"><h3>${zones[z][0]}</h3><p>${tx('z'+(i+1))}</p></div>`).join('')}</section><section class="section"><div class="section-title"><h2>${tx('science')}<span class="lime">.</span></h2><span class="pill">METHOD / 01</span></div><div class="science"><b>01 / WEIGHTED TASTE SCORE</b><p>${tx('sci1')}</p></div><div class="science"><b>02 / LABEL INTELLIGENCE</b><p>${tx('sci2')}</p></div><div class="science"><b>03 / THE EDITORIAL STANDARD</b><p>${tx('sci3')}</p></div></section><section class="section"><div class="section-title"><h2>${tx('index')}<span class="lime">.</span></h2></div>${fizzIndex()}</section></div>`}
function fizzIndex(){let pool=all().filter(d=>(s.filter==='all'||s.filter==='own'&&!d.sample||d.cat===s.filter)&&(d.name+' '+d.brand).toLowerCase().includes(s.q.toLowerCase()));pool.sort((a,b)=>s.sort==='score'?b.score-a.score:s.sort==='sugar'?a.sugar-b.sugar:a.name.localeCompare(b.name));return `<div class="filters">${[['all',tx('all')],['Citrus','CITRUS'],['Cola','COLA'],['Berry','BERRY'],['Fruit','FRUIT'],['Spicy','SPICY'],['own',tx('own')]].map(([x,l])=>`<button class="chip ${s.filter===x?'on':''}" data-filter="${x}">${l}</button>`).join('')}</div><div class="searchrow">⌕ <input data-query value="${esc(s.q)}" placeholder="${tx('search')}"><select data-sort><option value="score" ${s.sort==='score'?'selected':''}>TASTE ↓</option><option value="sugar" ${s.sort==='sugar'?'selected':''}>SUGAR ↑</option><option value="name" ${s.sort==='name'?'selected':''}>A–Z</option></select></div><div class="cardgrid">${pool.map(card).join('')}</div>`}
function fridge(){return `<div class="pad"><div class="key">THE PERSONAL SODA ARCHIVE</div><h1>THE<br><span class="lime">FRIDGE.</span></h1><p class="lead">${tx('fridgeIntro')}</p><section class="section"><div class="section-title"><h2>${tx('allCards')}<span class="lime">.</span></h2><span class="pill">${all().length} CARDS</span></div>${fizzIndex()}</section><button class="add" data-add title="Add drink">+</button></div>`}
function brandStats(){let us=unique(),n=us.length;const mean=k=>n?(us.reduce((a,d)=>a+(Number.isFinite(d[k])?d[k]:0),0)/n).toFixed(1):'—';const hallCount=us.filter(hall).length;const kpis=`<div class="data-stats"><div><b>${mean('score')}</b><small>Ø TASTE / 10</small></div><div><b>${mean('sugar')}</b><small>Ø SUGAR / 100ml</small></div><div><b>${hallCount}</b><small>HALL ENTRIES</small></div></div>`;const make=kind=>{let counts={};for(const d of us){let k=d[kind]||'?';counts[k]=(counts[k]||0)+1}return Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([k,v])=>`<div class="insight"><b>${esc(k)}</b><div class="bar"><i style="width:${v/Math.max(1,n)*100}%"></i></div><small>${v}</small></div>`).join('')||`<p class="muted">${tx('noData')}</p>`};return `<section class="section"><div class="section-title"><h2>${tx('stats')}<span class="lime">.</span></h2></div>${kpis}<div class="flat"><div class="key">${tx('brandStats')}</div>${make('maker')}<div class="key" style="margin-top:17px">${tx('countryStats')}</div>${make('country')}</div></section>`}
function myFizz(){let x=xp(),r=curRank(),next=ranks[r+1],prog=next?Math.min(100,100*(x-ranks[r][1])/(next[1]-ranks[r][1])):100;let my=unique(),cats=new Set(my.map(d=>d.cat)),hof=my.filter(hall).length,badges=[['✳','FIRST POP',my.length>=1],['◈','LABEL HUNTER',my.filter(d=>d.productPhoto&&d.nutriPhoto).length>=5],['⚡','NO SWEETENER HERO',hof>=3],['◎','FLAVOR HOPPER',cats.size>=4],['◆','TEN SIPS',my.length>=10],['✦','SODA GLOBE',new Set(my.map(d=>d.country)).size>=5]];return `<div class="pad"><div class="key">YOUR COLLECTION. YOUR CREDENTIALS.</div><h1>MY<br><span class="lime">FIZZ.</span></h1><p class="lead">${tx('meIntro')}</p><div class="rankhero"><div><div class="key">LEVEL ${String(r).padStart(2,'0')} · COLLECTOR</div><h2>${ranks[r][0]}<span class="lime">.</span></h2><p class="muted" style="margin-top:9px">${x} XP ${next?' / '+next[1]+' XP':''}</p></div><div class="medallion">✳</div></div><div class="track"><i style="width:${prog}%"></i></div><section class="section"><div class="section-title"><h2>${tx('ranks')}<span class="lime">.</span></h2><span class="pill">${r+1}/7</span></div>${ranks.map(([name,need],i)=>`<div class="rank ${i===r?'current':''}"><strong>${String(i).padStart(2,'0')}</strong><b>${name}</b><small>${i===r?'CURRENT':need+' XP'}</small></div>`).join('')}</section><section class="section"><div class="section-title"><h2>${tx('badges')}<span class="lime">.</span></h2></div><div class="badgegrid">${badges.map(([sym,name,earned])=>`<div class="badgecard"><span>${sym}</span><b>${name}</b><p class="fine">${earned?'✓ UNLOCKED':'🔒 LOCKED'}</p></div>`).join('')}</div></section><section class="section"><div class="section-title"><h2>${tx('passport')}<span class="lime">.</span></h2><span class="pill">${cats.size}/8</span></div><div class="passport">${sets.map(([k,ic])=>`<button data-set="${k}"><span>${ic}</span><small>${k.toUpperCase()} ${cats.has(k)?'✓':''}</small></button>`).join('')}</div><div id="fz5-set"></div></section>${brandStats()}<section class="section"><div class="flat"><div class="key">${tx('xp')}</div><p class="muted">${tx('xpText')}</p></div></section>${dataCentre()}<button class="add" data-add>+</button></div>`}
function detail(){let d=all().find(x=>x.id===s.detail);if(!d){s.detail=null;return home()}let z=zones[zone(d)];return `<div class="pad"><button class="back" data-back>← ${tx('back')}</button><div class="key" style="margin-top:20px">FIZZMAP® / ${esc(d.cat.toUpperCase())} / ${d.pack==='can'?'CAN':'BOTTLE'}</div><h1>${esc(d.name)}<span class="lime">.</span></h1><p class="lead">${esc(d.brand)} · ${esc(d.country||'—')}</p><div class="detail-photo">${pack(d)}</div><p style="margin-top:12px"><span class="mini-tag" style="border-color:${z[1]};color:${z[1]}">${zone(d)==='hof'&&!hall(d)?'HALL ZONE / NOT QUALIFIED':z[0]}</span> <span class="mini-tag">${hall(d)?'✓ HALL OF FAME':'HALL NOT CLEARED'}</span></p><div class="metrics"><div class="metric"><small>${tx('taste')}</small><b>${Number.isFinite(d.score)?d.score.toFixed(1):'—'}/10</b></div><div class="metric"><small>${tx('sugar')}</small><b>${Number.isFinite(d.sugar)?d.sugar.toFixed(1):'—'} g</b><small> /100 ml · ${Number.isFinite(d.sugar)?(d.sugar*(d.size||330)/100).toFixed(1):'—'} g / ${d.size||330}ml</small></div></div><p class="lead">${esc(d.note||'')}</p>${!d.sample?`<div class="detail-actions"><button class="cta ghost" data-edititem="${esc(d.id)}">${s.lang==='de'?'BEARBEITEN':'EDIT'} ✎</button><button class="cta danger" data-deleteitem="${esc(d.id)}">${s.lang==='de'?'LÖSCHEN':'DELETE'}</button></div>`:''}<div class="flat" style="margin-top:16px"><div class="key">${tx('gate')}</div><p class="muted">${tx('sweet')}: <b>${tx(d.sweet)}</b> · ${hall(d)?tx('eligible'):tx('excluded')} ${!d.sample&&d.sweet==='no'&&!d.nutriPhoto?' · '+(s.lang==='de'?'Nährwertfoto erforderlich':'Nutrition photo required'):''}</p></div><section class="section"><h2>${tx('where')}<span class="lime">.</span></h2><p class="muted" style="margin-top:8px">${tx('bought')}: <b>${esc(d.bought||'—')}</b><br>${tx('enjoyed')}: <b>${esc(d.enjoyed||'—')}</b><br>${tx('maker')}: <b>${esc(d.maker||'—')}</b></p></section><section class="section"><div class="section-title"><h2>${tx('photos')}<span class="lime">.</span></h2><span class="pill">COMING SOON</span></div><p class="muted">${tx('photosCopy')}</p><div class="community">${d.productPhoto?`<div class="shot"><img src="${d.productPhoto}" alt="Produktfoto"></div>`:''}${d.nutriPhoto?`<div class="shot"><img src="${d.nutriPhoto}" alt="Nährwertfoto"></div>`:''}${s.shot?`<div class="shot"><img src="${s.shot}" alt="Local photo"></div>`:''}<label class="shot" for="fz5-community">＋<br>${tx('shot')}</label><input id="fz5-community" type="file" accept="image/*" style="display:none"></div></section></div>`}
const ratingNames=['GESCHMACK','ERFRISCHUNG','MUNDGEFÜHL','BALANCE','NACHGESCHMACK','ORIGINALITÄT'];const weights=[.30,.20,.20,.15,.10,.05];const getScore=()=>Math.max(0,(s.edit?.ratings.reduce((a,v,i)=>a+v*weights[i],0)||0)-(Number(s.edit?.penalty)||0));
function editor(){let d=s.edit;return `<div class="pad"><button class="back" data-back>← ${tx('back')}</button><div class="key" style="margin-top:20px">THE TASTING LAB / ADD</div><h1>${tx('new')}</h1><div class="detail-photo">${pack(d)}</div><p class="fine" style="margin-top:9px">${s.lang==='de'?'Etikett wird auf der gewählten Verpackung angezeigt.':'The label is rendered on your selected package.'}</p><label class="field">${tx('pack')}</label><div class="filters"><button data-pack="can" class="chip ${d.pack==='can'?'on':''}">${tx('can')}</button><button data-pack="bottle" class="chip ${d.pack==='bottle'?'on':''}">${tx('bottle')}</button></div><label class="field">${tx('name')}</label><input class="input" data-edit="name" value="${esc(d.name)}" placeholder="Citrus Drop"><label class="field">${tx('brand')}</label><input class="input" data-edit="brand" value="${esc(d.brand)}" placeholder="New Soda Club"><label class="field">${tx('maker')}</label><input class="input" data-edit="maker" value="${esc(d.maker)}" placeholder="Manufacturer"><label class="field">${tx('country')}</label><input class="input" data-edit="country" value="${esc(d.country)}" placeholder="DE / US / JP"><label class="field">${tx('cat')}</label><select class="input" data-edit="cat">${sets.map(([k])=>`<option ${k===d.cat?'selected':''}>${k}</option>`).join('')}</select><label class="field">${tx('sugarG')} · <span data-val="sugar">${d.sugar}</span></label><input class="range" data-edit="sugar" type="range" min="0" max="16" step=".1" value="${d.sugar}"><label class="field">${tx('size')}</label><input class="input" type="number" min="100" max="2500" data-edit="size" value="${d.size}"><label class="field">${tx('sweet')}</label><select class="input" data-edit="sweet"><option value="unknown" ${d.sweet==='unknown'?'selected':''}>${tx('unknown')}</option><option value="no" ${d.sweet==='no'?'selected':''}>${tx('no')}</option><option value="yes" ${d.sweet==='yes'?'selected':''}>${tx('yes')}</option></select><label class="field">${tx('bought')}</label><input class="input" data-edit="bought" value="${esc(d.bought)}" placeholder="Späti / Trader Joe's / Market"><label class="field">${tx('enjoyed')}</label><input class="input" data-edit="enjoyed" value="${esc(d.enjoyed)}" placeholder="Trier / NYC / ..."><label class="field">${tx('date')}</label><input class="input" data-edit="date" type="date" value="${d.date}"><div class="section"><div class="key">THE SIX-POINT TASTE PROFILE</div><h2>${tx('scoreLabel')} <span class="lime" id="fz5-score">${getScore().toFixed(1)}</span></h2>${ratingNames.map((n,i)=>`<label class="field">${n} · ${Math.round(weights[i]*100)}% / <span data-rating-label="${i}">${d.ratings[i]}</span></label><input class="range" type="range" data-rating="${i}" min="0" max="10" step=".5" value="${d.ratings[i]}">`).join('')}</div><label class="field">${s.lang==='de'?'TASTING NOTES':'TASTING NOTES'}</label><textarea class="input" rows="3" data-edit="note" placeholder="${s.lang==='de'?'Aroma, Eindruck, Besonderheiten …':'Aroma, notes, highlights …'}">${esc(d.note||'')}</textarea><label class="field">${s.lang==='de'?'PERSÖNLICHER SÜẞSTOFF-ABZUG':'PERSONAL SWEETENER PENALTY'} · <span data-val="penalty">${d.penalty||0}</span> / 2</label><input class="range" type="range" data-edit="penalty" min="0" max="2" step=".5" value="${d.penalty||0}"><label class="checkrow"><input type="checkbox" data-edit="tasted" ${d.tasted?'checked':''}> ${tx('tasted')}</label><label class="field">${tx('label')} ${d.art?'<span class="lime">✓</span>':''}</label><input class="upload" type="file" data-image="art" accept="image/*"><label class="field">${s.lang==='de'?'ETIKETTGRÖSSE':'LABEL ZOOM'} · <span data-val="zoom">${d.zoom||1}</span>×</label><input class="range" type="range" data-edit="zoom" min="1" max="2" step=".05" value="${d.zoom||1}"><label class="field">${s.lang==='de'?'ETIKETTPOSITION':'LABEL POSITION'} · <span data-val="shift">${d.shift||0}</span>%</label><input class="range" type="range" data-edit="shift" min="-50" max="50" step="5" value="${d.shift||0}"><label class="field">${tx('original')} ${d.productPhoto?'<span class="lime">✓</span>':''}</label><input class="upload" type="file" data-image="productPhoto" accept="image/*"><label class="field">${tx('nutrition')} ${d.nutriPhoto?'<span class="lime">✓</span>':''}</label><input class="upload" type="file" data-image="nutriPhoto" accept="image/*"><button class="cta" data-save style="width:100%;margin-top:19px">${tx('save')} ↗</button><p class="notice">${tx('local')}</p></div>`}
function compare(){const d1=data[1],d2=data[0];return `<div class="pad"><button class="back" data-nav="home">← ${tx('back')}</button><div class="key" style="margin-top:20px">SUGAR SWAP / SIDE-BY-SIDE</div><h1>LESS SUGAR.<br><span class="lime">MORE FIZZ.</span></h1><p class="lead">${s.lang==='de'?'Gleiche Portion, weniger Zucker – beide Drinks nach derselben Skala vergleichen.':'Same volume, less sugar — compare two drinks on one scale.'}</p><div class="cardgrid" style="margin-top:20px">${[d1,d2].map(card).join('')}</div><div class="flat" style="margin-top:15px"><div class="key">SUGAR DIFFERENCE / 330 ML</div><h2 class="lime">−${((d1.sugar-d2.sugar)*3.3).toFixed(1)} g</h2><p class="muted" style="margin-top:8px">${s.lang==='de'?'Ein illustrativer Vergleich zweier fiktiver Konzeptgetränke.':'An illustrative comparison of fictional concept drinks.'}</p></div></div>`}
function manifesto(){return `<div class="pad"><button class="back" data-nav="home">← ${tx('back')}</button><div class="key" style="margin-top:20px">THE BETTER FIZZ CHALLENGE / 001</div><h1>MAKE BETTER<br><span class="lime">SODA.</span></h1><p class="lead">${s.lang==='de'?'Weniger Zucker, voller Geschmack, keine Süßstoffe. FIZZMAP belohnt das Ergebnis statt das Marketingbudget.':'Less sugar, full flavor, no sweetener shortcuts. FIZZMAP rewards the result — not the ad spend.'}</p><div class="feature" style="margin-top:20px"><div class="key">#CUTSUGARKEEPTHEKICK</div><h2>PROVE THE<br>FLAVOR.</h2><p class="muted">${s.lang==='de'?'Ein offener Aufruf an Hersteller: Bringt uns die nächste Hall-of-Fame-Dose.':'An open call to manufacturers: bring us the next Hall of Fame can.'}</p></div><div class="section"><div class="key">THE INDEPENDENCE PLEDGE</div><p class="lead">${s.lang==='de'?'Keine gekauften Topplätze. Keine erfundenen Reviews. Klare Datengrundlagen, echte Verkostungen und sichtbare Interessenkonflikte.':'No paid rankings. No invented reviews. Transparent data, real tastings, disclosed interests.'}</p><button class="cta" data-nav="map" style="margin-top:18px">${tx('goMap')} ↗</button></div></div>`}

function dataCentre(){const own=s.items.length,photos=s.items.reduce((n,d)=>n+['art','productPhoto','nutriPhoto'].filter(k=>typeof d[k]==='string'&&d[k].startsWith('data:image/')).length,0);return `<section class="section"><div class="section-title"><h2>${s.lang==='de'?'DEINE DATEN':'YOUR DATA'}<span class="lime">.</span></h2><span class="pill">OWN YOUR DATA</span></div><div class="data-stats"><div><b>${own}</b><small>${s.lang==='de'?'EIGENE DRINKS':'YOUR DRINKS'}</small></div><div><b>${data.length}</b><small>STUDIO CARDS</small></div><div><b>${photos}</b><small>FOTO-DATEIEN</small></div></div><div class="data-actions"><button class="cta" data-export="json">↓ ${s.lang==='de'?'VOLLSTÄNDIGES JSON-BACKUP':'FULL JSON BACKUP'}</button><button class="cta ghost" data-export="csv">↓ CSV / ${s.lang==='de'?'ALLE KARTEN':'ALL CARDS'}</button><button class="cta ghost" data-export="mine">↓ CSV / ${s.lang==='de'?'NUR EIGENE':'MY DRINKS ONLY'}</button><button class="cta ghost" data-import>↑ ${s.lang==='de'?'BACKUP WIEDERHERSTELLEN':'RESTORE BACKUP'}</button><input type="file" accept=".json,application/json" id="fizz-import" hidden></div><div id="fizz-export-report" class="export-report" role="status" aria-live="polite">${s.lang==='de'?'CSV enthält alle Felder und Datensätze. JSON enthält zusätzlich sämtliche gespeicherten Bilder.':'CSV includes all records and text fields. JSON also embeds every stored image.'}</div><p class="notice">${s.lang==='de'?'Die 8 Studio-Karten sind fiktive Designbeispiele, keine realen Produkttests. Beim CSV-Gesamtexport sind sie ausdrücklich gekennzeichnet. Ein JSON-Backup sichert deine eigenen Drinks und dokumentiert die mitgelieferten Studio-Karten.':'The 8 studio cards are fictional. Full CSV marks them clearly. JSON backs up your drinks and documents the bundled studio catalog.'}</p></section>`}
function toast(msg){let el=document.getElementById('fizz-toast');if(!el){el=document.createElement('div');el.id='fizz-toast';el.setAttribute('role','status');document.body.append(el)}el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3700)}
function report(msg){lastExport=msg;const el=R.querySelector('#fizz-export-report');if(el)el.textContent=msg;toast(msg)}
function normalize(d){if(!d||typeof d!=='object'||typeof d.name!=='string'||!d.name.trim())throw Error('Invalid drink');
 const ratingNames=['taste','refreshment','mouthfeel','balance','aftertaste','originality'];
 const rs=Array.isArray(d.ratings)?d.ratings.map(v=>Number(v)):ratingNames.map(k=>Number(d.ratings?.[k]??7));
 const score=Math.max(0,rs.reduce((sum,v,i)=>sum+Math.max(0,Math.min(10,v||0))*weights[i],0)-(Number(d.penalty)||0));
 const safeImg=v=>typeof v==='string'&&v.length<18_000_000&&/^data:image\/(?:jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(v)?v:null;
 const sugar=d.sugar===null||d.sugar===''||d.sugar===undefined?null:Number(d.sugar);
 const sweet=d.sweet==='no'||d.sweet==='yes'?d.sweet:(d.sweeteners===true?'yes':'unknown');
 return {id:String(d.id||'fizz-'+Date.now()+'-'+Math.random().toString(36).slice(2)),name:String(d.name).slice(0,120),brand:String(d.brand||'').slice(0,120),maker:String(d.maker||d.brand||''),country:String(d.country||d.origin||''),cat:String(d.cat||d.category||'Other'),sugar:Number.isFinite(sugar)?Math.max(0,Math.min(50,sugar)):null,size:Math.max(1,Math.min(5000,Number(d.size)||330)),sweet,pack:d.pack==='bottle'||d.packaging==='bottle'?'bottle':'can',color:/^#[0-9a-fA-F]{6}$/.test(d.color)?d.color:'#d8ff52',note:String(d.note||'').slice(0,5000),date:String(d.date||new Date().toISOString().slice(0,10)).slice(0,25),bought:String(d.bought||''),enjoyed:String(d.enjoyed||''),ratings:rs,score:(d.tasted===false||d.status==='wishlist')?null:Math.round((Array.isArray(d.ratings)||d.ratings&&typeof d.ratings==='object'?score:Number(d.score)||score)*10)/10,tasted:d.tasted!==undefined?Boolean(d.tasted):d.status!=='wishlist',art:safeImg(d.art)||safeImg(d.coverLabelPhoto)||null,productPhoto:safeImg(d.productPhoto)||safeImg(d.photo)||null,nutriPhoto:safeImg(d.nutriPhoto)||safeImg(d.labelPhoto)||null,zoom:Math.max(1,Math.min(2,Number(d.zoom||d.labelZoom)||1)),shift:Math.max(-50,Math.min(50,Number(d.shift??d.labelOffset)||0)),penalty:Math.max(0,Math.min(2,Number(d.penalty)||0)),sample:false};
}
function nativeBridge(){return !!window.webkit?.messageHandlers?.fizzmap}
function sendNative(msg){try{window.webkit.messageHandlers.fizzmap.postMessage(msg);return true}catch(_){return false}}
function nativeTransfer(operation,content,name='',mime='',requestId=''){const id=requestId||'transfer-'+Date.now()+'-'+Math.random().toString(36).slice(2),size=300000,total=Math.max(1,Math.ceil(content.length/size));for(let index=0;index<total;index++){if(!sendNative({type:'chunk',operation,requestId:id,index,total,content:content.slice(index*size,(index+1)*size),name,mime}))throw Error('Native transfer failed')}return id}
async function openDatabase(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('IndexedDB unavailable'));const req=indexedDB.open('fizzmap_db',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('kv'))req.result.createObjectStore('kv')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbRead(){if(!db)return null;return new Promise((resolve,reject)=>{const req=db.transaction('kv','readonly').objectStore('kv').get('drinks');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbWrite(items){if(!db)return;return new Promise((resolve,reject)=>{const tx=db.transaction('kv','readwrite');tx.objectStore('kv').put(items,'drinks');tx.oncomplete=()=>resolve(true);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function persist(){if(!storageReady)throw Error('Storage not ready');try{if(nativeBridge()){await new Promise((resolve,reject)=>{const id='save-'+Date.now()+'-'+Math.random().toString(36).slice(2);nativePending.set(id,{resolve,reject});nativeTransfer('save',JSON.stringify({app:'FIZZMAP',schema:2,drinks:s.items,lang:s.lang}),'','',id);setTimeout(()=>{if(nativePending.has(id)){nativePending.delete(id);reject(Error('Native save timed out'))}},10000)})}else if(db){await dbWrite(s.items)}else{localStorage.setItem('fizzmap_fallback_v2',JSON.stringify(s.items))}return true}catch(e){console.error('FIZZMAP save failed',e);toast(s.lang==='de'?'Speichern fehlgeschlagen – bitte Speicher prüfen.':'Save failed – check device storage.');return false}}
async function initialize(){try{const storedLang=localStorage.getItem('fizzmap.lang');if(storedLang==='en')s.lang='en'}catch(_){ }
 if(nativeBridge()){storageReady=true;render();sendNative({type:'ready'});return}
 try{db=await openDatabase();const previous=await dbRead();if(Array.isArray(previous))s.items=previous.filter(d=>!d.demo&&!d.sample).map(normalize);else{const fallback=localStorage.getItem('fizzmap_fallback_v2');if(fallback)s.items=JSON.parse(fallback).map(normalize)}storageReady=true;render()}catch(e){console.warn('IndexedDB unavailable',e);try{const fallback=localStorage.getItem('fizzmap_fallback_v2');if(fallback)s.items=JSON.parse(fallback).map(normalize);storageReady=true;render();toast('Fallback storage active')}catch(_){storageReady=true;render();toast('Storage unavailable: export before closing')}}}
window.FizzNative={saved:function(payload){const pending=nativePending.get(payload?.id);if(!pending)return;nativePending.delete(payload.id);payload.ok?pending.resolve(true):pending.reject(Error(payload.error||'Native save failed'))},restore:function(payload){try{if(payload?.drinks&&Array.isArray(payload.drinks))s.items=payload.drinks.map(normalize);if(payload?.lang==='en')s.lang='en';storageReady=true;render();toast(s.lang==='de'?`${s.items.length} Drinks geladen`:`${s.items.length} drinks loaded`)}catch(e){console.error(e)}},import:function(payload){restoreData(payload)}};
function csvSafe(v){let x=String(v??'');if(/^[=+@\t\r]/.test(x)||(/^-(?!\d+(?:[.,]\d+)?$)/.test(x)))x="'"+x;return '"'+x.replaceAll('"','""')+'"'}
function fullCSV(onlyMine=false){const columns=['record_type','id','name','brand','manufacturer','country','category','packaging','size_ml','sugar_g_per_100ml','sugar_g_per_package','sweeteners','taste_score','tasted','purchase_location','enjoyed_location','tasting_date','taste','refreshment','mouthfeel','balance','aftertaste','originality','sweetener_penalty','note','cover_photo','product_photo','nutrition_photo'];const items=onlyMine?[...s.items]:[...data,...s.items];const rows=items.map(d=>[d.sample?'FICTIONAL_STUDIO':'PERSONAL',d.id,d.name,d.brand,d.maker,d.country,d.cat,d.pack,d.size,d.sugar??'',Number.isFinite(d.sugar)?(d.sugar*d.size/100).toFixed(2):'',d.sweet,d.score,d.tasted??'',d.bought||'',d.enjoyed||'',d.date||'',...(Array.isArray(d.ratings)?d.ratings:Array(6).fill('')),d.penalty||0,d.note||'',!!d.art,!!d.productPhoto,!!d.nutriPhoto]);const csv='\ufeff'+[columns,...rows].map(r=>r.map(csvSafe).join(';')).join('\r\n');if(csv.split('\r\n').length!==rows.length+1)throw Error('CSV row count mismatch');return {csv,rows:rows.length,personal:s.items.length,samples:onlyMine?0:data.length}}
function backup(){const obj={app:'FIZZMAP',schema:2,exportedAt:new Date().toISOString(),lang:s.lang,drinks:s.items,catalog:data.map(({art,...d})=>({...d,art}))};const json=JSON.stringify(obj,null,2);const test=JSON.parse(json);if(test.drinks.length!==s.items.length||test.catalog.length!==data.length)throw Error('Backup count mismatch');for(let i=0;i<s.items.length;i++)for(const key of ['art','productPhoto','nutriPhoto'])if((test.drinks[i][key]||null)!==(s.items[i][key]||null))throw Error('Photo missing from backup');return {json,drinks:test.drinks.length,catalog:test.catalog.length,photos:test.drinks.reduce((n,d)=>n+['art','productPhoto','nutriPhoto'].filter(k=>!!d[k]).length,0)}}
function downloadFile(name,content,mime){if(nativeBridge()){nativeTransfer('export',content,name,mime);return}const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function exportFile(kind){try{const stamp=new Date().toISOString().slice(0,10);if(kind==='json'){const b=backup();downloadFile('FIZZMAP_Full_Backup_'+stamp+'.json',b.json,'application/json');report(`${b.drinks} ${s.lang==='de'?'eigene Drinks':'personal drinks'} · ${b.catalog} Studio · ${b.photos} Fotos · JSON ✓`)}else{const r=fullCSV(kind==='mine');if(kind==='mine'&&!r.personal){toast(s.lang==='de'?'Noch keine eigenen Drinks. Nutze CSV / Alle Karten.':'No personal drinks yet. Use CSV / All cards.');return}downloadFile('FIZZMAP_'+(kind==='mine'?'My_Drinks':'Full_Index')+'_'+stamp+'.csv',r.csv,'text/csv;charset=utf-8');report(`${r.rows} ${s.lang==='de'?'Datensätze':'records'} (${r.personal} ${s.lang==='de'?'eigene':'personal'}, ${r.samples} Studio) · CSV ✓`)}}catch(e){console.error(e);toast('Export error: '+e.message)}}
async function restoreData(obj){try{if(!obj||obj.app!=='FIZZMAP'||![1,2].includes(Number(obj.schema))||!Array.isArray(obj.drinks)||obj.drinks.length>10000)throw Error('Not a valid FIZZMAP backup');const incoming=obj.drinks.filter(d=>!d.demo&&!d.sample).map(normalize);const ok=confirm(s.lang==='de'?`Backup mit ${incoming.length} eigenen Drinks importieren? Deine ${s.items.length} aktuellen Einträge werden ersetzt.`:`Import ${incoming.length} drinks? This replaces ${s.items.length} existing drinks.`);if(!ok)return;const old=s.items;s.items=incoming;if(!await persist()){s.items=old;return}nav('fridge');toast(`${incoming.length} ${s.lang==='de'?'Drinks wiederhergestellt':'drinks restored'} ✓`)}catch(e){toast((s.lang==='de'?'Import fehlgeschlagen: ':'Import failed: ')+e.message)}}
async function readPhoto(file){if(!file||!file.type.startsWith('image/'))throw Error('Please choose an image');if(file.size>28*1024*1024)throw Error('Image larger than 28 MB');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(Error('Cannot read image'));r.readAsDataURL(file)});return await new Promise(resolve=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,1400/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.84))};img.onerror=()=>/^data:image\/(?:jpeg|png|webp);base64,/.test(data)?resolve(data):reject(Error('Fotoformat konnte nicht verarbeitet werden. Bitte JPEG oder PNG verwenden.'));img.src=data})}

function render(keep=false){let top=M.scrollTop;M.innerHTML=s.detail?detail():s.tab==='edit'?editor():s.tab==='map'?mapPage():s.tab==='fridge'?fridge():s.tab==='me'?myFizz():s.tab==='swap'?compare():s.tab==='manifesto'?manifesto():home();M.scrollTop=keep?top:0;R.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('on',b.dataset.lang===s.lang));R.querySelectorAll('[data-nav]').forEach(b=>{let on=s.tab===b.dataset.nav;b.classList.toggle('active',on);let small=b.querySelector('small');if(small)small.textContent=tx(b.dataset.nav)})}
function nav(x){s.tab=x;s.detail=null;s.peek=null;render(false)}
R.addEventListener('click',async e=>{let b=e.target.closest('[data-nav],[data-lang],[data-feature],[data-detail],[data-point],[data-close],[data-mode],[data-filter],[data-add],[data-back],[data-pack],[data-save],[data-set],[data-export],[data-import],[data-edititem],[data-deleteitem]');if(!b)return;let d=b.dataset;if(d.export){exportFile(d.export);return}if('import'in d){R.querySelector('#fizz-import')?.click();return}if(d.edititem){let target=s.items.find(x=>x.id===d.edititem);if(target){s.edit=JSON.parse(JSON.stringify(target));s.detail=null;nav('edit')}return}if(d.deleteitem){let target=s.items.find(x=>x.id===d.deleteitem);if(target&&confirm((s.lang==='de'?'Drink wirklich löschen? ':'Delete drink? ')+target.name)){const previous=s.items;s.items=s.items.filter(x=>x.id!==target.id);if(await persist()){nav('fridge')}else{s.items=previous}}return}if(d.nav){nav(d.nav);return}if(d.lang){s.lang=d.lang;try{localStorage.setItem('fizzmap.lang',s.lang)}catch(_){}if(nativeBridge())sendNative({type:'language',lang:s.lang});render(true);return}if(d.feature){nav(d.feature==='swap'?'swap':'manifesto');return}if(d.detail){s.detail=d.detail;s.peek=null;render(false);return}if(d.point){s.peek=d.point;render(true);return}if('close' in d){s.peek=null;render(true);return}if(d.mode){s.mode=d.mode;s.peek=null;render(true);return}if(d.filter){s.filter=d.filter;render(true);return}if('back'in d){s.detail=null;nav('fridge');return}if('add'in d){s.edit={id:null,name:'',brand:'',maker:'',country:'',cat:'Citrus',sugar:4,size:330,score:7.5,sweet:'unknown',bought:'',enjoyed:'',date:new Date().toISOString().slice(0,10),pack:'can',ratings:[8,8,8,8,8,8],tasted:true,art:null,productPhoto:null,nutriPhoto:null,zoom:1,shift:0,penalty:0,note:''};nav('edit');return}if(d.pack){s.edit.pack=d.pack;render(true);return}if(d.set){let r=R.querySelector('#fz5-set');if(r)r.innerHTML=`<p class="muted" style="margin-top:12px">${sets.find(v=>v[0]===d.set)?.[1]} ${d.set} / +20 XP · ${s.lang==='de'?'Einmaliger Bonus für die erste echte Verkostung aus dieser Geschmackswelt.':'One-time bonus for your first real tasting in this flavor world.'}</p>`;return}if('save'in d){if(!s.edit.name.trim()){R.querySelector('[data-edit="name"]')?.focus();return}let scores=getScore();const item=normalize({...s.edit,id:s.edit.id||'fizz-'+(crypto.randomUUID?.()||Date.now()),score:Math.round(scores*10)/10,sample:false});const old=s.items;s.items=[...s.items.filter(x=>x.id!==item.id),item];if(await persist()){nav('fridge');toast(s.lang==='de'?'Drink & Fotos gespeichert ✓':'Drink & photos saved ✓')}else{s.items=old}return}});
R.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.hasAttribute('data-point')){e.preventDefault();s.peek=e.target.dataset.point;render(true)}});
R.addEventListener('input',e=>{let k=e.target.dataset.edit;if(k){s.edit[k]=k==='tasted'?e.target.checked:['sugar','size','zoom','shift','penalty'].includes(k)?Number(e.target.value):e.target.value;const l=R.querySelector(`[data-val="${k}"]`);if(l)l.textContent=e.target.value;if(k==='zoom'||k==='shift'){let p=R.querySelector('.detail-photo .vessel');if(p)p.style.setProperty(k==='zoom'?'--label-zoom':'--label-shift',e.target.value+(k==='shift'?'%':''))}if((k==='name'||k==='brand')&&!s.edit.art){let label=R.querySelector('.detail-photo .label-design');if(label)label.innerHTML=`<span class="label-brand">${esc(s.edit.brand||'SODA CULTURE')}</span><strong>${esc(s.edit.name||'NEW DROP')}</strong><span class="label-caption">FIZZMAP®</span>`}return}if(e.target.hasAttribute('data-rating')){const i=+e.target.dataset.rating;s.edit.ratings[i]=+e.target.value;R.querySelector(`[data-rating-label="${i}"]`).textContent=e.target.value;R.querySelector('#fz5-score').textContent=getScore().toFixed(1);return}if(e.target.hasAttribute('data-query')){let pos=e.target.selectionStart;s.q=e.target.value;render(true);let input=R.querySelector('[data-query]');input?.focus();try{input?.setSelectionRange(pos,pos)}catch(_){}return}});
R.addEventListener('change',async e=>{if(e.target.id==='fizz-import'&&e.target.files?.[0]){try{const txt=await e.target.files[0].text();await restoreData(JSON.parse(txt))}catch(err){toast('Import error: '+err.message)}e.target.value='';return}if(e.target.hasAttribute('data-sort')){s.sort=e.target.value;render(true);return}if(e.target.dataset.image||e.target.id==='fz5-community'){try{const photo=await readPhoto(e.target.files?.[0]);if(e.target.id==='fz5-community'){s.shot=photo;render(true)}else{s.edit[e.target.dataset.image]=photo;if(e.target.dataset.image==='art'){const label=R.querySelector('.detail-photo .vessel-label');if(label)label.innerHTML='<img class="label-art" src="'+photo+'" alt="">'}const status=e.target.closest('label')?.previousElementSibling;toast(s.lang==='de'?'Bild für Karte übernommen ✓':'Image added to card ✓')}}catch(err){toast(err.message)}}});

initialize();
if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(console.warn);
